#!/usr/bin/env bash
# Generated by Phase: IMPLEMENT | Feature: EVOL-081
# Validate the delivered pipelines against the platforms' LIVE schemas (EVOL-081 RDR 3: fetched at run time, no copy kept).
#   GitHub Actions: https://json.schemastore.org/github-workflow.json   (every .github/workflows/*.yml)
#   Bitbucket:      https://api.bitbucket.org/schemas/pipelines-configuration   (bitbucket-pipelines.yml)
# Usage: test-pipeline-schemas.sh [DIR]   DIR = a materialised project (default: the template sources —
#        .context/templates/setup/workflows/*.github-actions.yml and *.bitbucket.yml, each validated as a whole file).
# A schema that cannot be fetched: red when CI=true, otherwise «skipped — schema unreachable» (exit 0, never green).
# Production approval is no schema property: gate.py delivery --check judges it.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
DIR="${1:-}"
WORK="$(mktemp -d)"; trap 'rm -rf "$WORK"' EXIT
GH_URL="https://json.schemastore.org/github-workflow.json"
BB_URL="https://api.bitbucket.org/schemas/pipelines-configuration"

if [ -n "$DIR" ]; then
  GH_FILES=$(ls "$DIR"/.github/workflows/*.yml 2>/dev/null || true)
  BB_FILES=$(ls "$DIR"/bitbucket-pipelines.yml 2>/dev/null || true)
else
  GH_FILES=$(ls "$ROOT"/.context/templates/setup/workflows/*.github-actions.yml 2>/dev/null || true)
  BB_FILES=$(ls "$ROOT"/.context/templates/setup/workflows/*.bitbucket.yml 2>/dev/null || true)
fi

FAIL=0
fetch() {   # $1 url, $2 out → 0 fetched · 1 unreachable
  curl --fail --silent --show-error --location --retry 3 --max-time 60 -o "$2" "$1" 2>/dev/null
}
check() {   # $1 label, $2 url, $3 files
  [ -n "$3" ] || { echo "  - $1: no file to validate"; return 0; }
  local schema="$WORK/$1.json"
  if ! fetch "$2" "$schema"; then
    if [ "${CI:-}" = "true" ]; then echo "  ✗ $1: schema unreachable ($2) — red in CI, never a silent pass"; FAIL=1
    else echo "  - $1: skipped — schema unreachable ($2); not validated"; fi
    return 0
  fi
  # shellcheck disable=SC2086
  OUT=$(python3 -I - "$schema" $3 <<'PY'
import json, sys
import yaml, jsonschema
schema = json.load(open(sys.argv[1]))
cls = jsonschema.validators.validator_for(schema)
bad = 0
for f in sys.argv[2:]:
    doc = yaml.safe_load(open(f))
    if isinstance(doc, dict) and True in doc:   # YAML 1.1 reads the `on:` key as a boolean; the schema names it `on`
        doc["on"] = doc.pop(True)
    errs = sorted(cls(schema).iter_errors(doc), key=lambda e: list(e.path))
    if errs:
        bad = 1
        print(f"✗ {f}: " + "; ".join(f"{'/'.join(map(str, e.path)) or '(root)'}: {e.message[:160]}" for e in errs[:5]))
    else:
        print(f"✓ {f}")
sys.exit(bad)
PY
)
  local rc=$?
  printf '%s\n' "$OUT" | sed 's/^/  /'
  [ "$rc" -eq 0 ] || FAIL=1
}
echo "── pipeline schemas (live) ──"
check github-workflow "$GH_URL" "$GH_FILES"
check bitbucket-pipelines "$BB_URL" "$BB_FILES"
exit "$FAIL"
